/// The layout item emitted between a list marker and paragraph content.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ListLevelSuffix {
    Tab,
    Space,
    Nothing,
}

/// Explicit restart behavior for a numbering level.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ListLevelRestart {
    /// Continue across every more-significant level.
    Never,
    /// Restart after the given zero-based, more-significant level.
    After(u32),
}

impl ListLevelRestart {
    fn from_st(value: u32) -> Self {
        if value == 0 {
            Self::Never
        } else {
            Self::After(value - 1)
        }
    }
}

impl ListLevelSuffix {
    fn from_st(value: ST_LvlSuffix) -> Self {
        match value {
            ST_LvlSuffix::Tab => Self::Tab,
            ST_LvlSuffix::Space => Self::Space,
            ST_LvlSuffix::Nothing => Self::Nothing,
        }
    }
}

/// Resolved reader metadata for one numbering definition level.
#[derive(Debug, Clone, PartialEq)]
pub struct NumberingLevel<'a> {
    /// The zero-based list level.
    pub level: u32,
    /// The marker format at this level.
    pub format: NumberingFormat<'a>,
    /// The exact OOXML format name, including producer-defined values.
    pub format_name: &'a str,
    /// The first marker value, defaulting to one when Word omits it.
    pub start: u32,
    /// The item emitted between the marker and paragraph content.
    pub suffix: ListLevelSuffix,
    /// The Word level-text template or bullet glyph.
    pub level_text: Option<&'a str>,
    /// The marker alignment, when explicitly configured.
    pub alignment: Option<crate::paragraph::Alignment>,
    /// The paragraph style associated with this numbering level.
    pub paragraph_style: Option<&'a str>,
    /// Explicit restart behavior. Absence means the OOXML default.
    pub restart: Option<ListLevelRestart>,
    /// Whether inherited placeholders use decimal legal numbering.
    pub legal_numbering: Option<bool>,
    /// Left indentation in twips.
    pub indent_left: Option<oxoffice_core::Twips>,
    /// Hanging indentation in twips.
    pub indent_hanging: Option<oxoffice_core::Twips>,
    /// First-line indentation in twips.
    pub indent_first_line: Option<oxoffice_core::Twips>,
    /// Typed properties applied only to the numbering marker.
    pub marker_properties: Option<&'a CT_RPr>,
    /// Producer template code from `w:tplc`.
    pub template_code: Option<&'a str>,
    /// Whether the producer marked this level tentative.
    pub tentative: Option<bool>,
    /// Whether this level retains semantic facts this projection does not model.
    pub has_unmodeled_properties: bool,
    /// Whether the list item has nonstandard paragraph-level presentation.
    pub has_paragraph_presentation: bool,
    /// Whether the marker has run-level presentation properties.
    pub has_marker_presentation: bool,
}

fn list_level_alignment(value: ST_Jc) -> crate::paragraph::Alignment {
    match value {
        ST_Jc::Center => crate::paragraph::Alignment::Center,
        ST_Jc::Right | ST_Jc::End => crate::paragraph::Alignment::Right,
        ST_Jc::Both | ST_Jc::Distribute => crate::paragraph::Alignment::Justify,
        _ => crate::paragraph::Alignment::Left,
    }
}

/// One level of a custom list definition for [`Document::add_list_definition`].
#[derive(Debug, Clone)]
pub struct ListLevel {
    /// Numbering format for this level.
    pub format: ListNumberFormat,
    /// Starting number (defaults to 1; ignored for bullet levels).
    pub start: Option<u32>,
    level_text: Option<String>,
    suffix: Option<ListLevelSuffix>,
    alignment: Option<crate::paragraph::Alignment>,
    indent_left: Option<oxoffice_core::Twips>,
    indent_hanging: Option<oxoffice_core::Twips>,
    indent_first_line: Option<oxoffice_core::Twips>,
    marker_properties: Option<CT_RPr>,
    legal_numbering: Option<bool>,
    restart: Option<ListLevelRestart>,
    template_code: Option<String>,
    tentative: Option<bool>,
    source_level: Option<Box<CT_Lvl>>,
}

impl PartialEq for ListLevel {
    fn eq(&self, other: &Self) -> bool {
        self.format == other.format
            && self.start == other.start
            && self.level_text == other.level_text
            && self.suffix == other.suffix
            && self.alignment == other.alignment
            && self.indent_left == other.indent_left
            && self.indent_hanging == other.indent_hanging
            && self.indent_first_line == other.indent_first_line
            && self.marker_properties == other.marker_properties
            && self.legal_numbering == other.legal_numbering
            && self.restart == other.restart
            && self.template_code == other.template_code
            && self.tentative == other.tentative
    }
}

impl ListLevel {
    /// A level with the given format, starting at 1.
    pub fn new(format: ListNumberFormat) -> Self {
        ListLevel {
            format,
            start: None,
            level_text: None,
            suffix: None,
            alignment: None,
            indent_left: None,
            indent_hanging: None,
            indent_first_line: None,
            marker_properties: None,
            legal_numbering: None,
            restart: None,
            template_code: None,
            tentative: None,
            source_level: None,
        }
    }

    /// A bullet level.
    pub fn bullet() -> Self {
        Self::new(ListNumberFormat::Bullet)
    }

    /// A decimal-numbered level.
    pub fn decimal() -> Self {
        Self::new(ListNumberFormat::Decimal)
    }

    /// Override the starting number for this level.
    pub fn start(mut self, start: u32) -> Self {
        self.start = Some(start);
        self
    }

    /// Set the level-text template or bullet glyph.
    pub fn level_text(mut self, value: impl Into<String>) -> Self {
        self.level_text = Some(value.into());
        self
    }

    /// Select the content emitted after the marker.
    pub fn suffix(mut self, value: ListLevelSuffix) -> Self {
        self.suffix = Some(value);
        self
    }

    /// Set marker alignment.
    pub fn alignment(mut self, value: crate::paragraph::Alignment) -> Self {
        self.alignment = Some(value);
        self
    }

    /// Set left, hanging, and first-line indentation in twips.
    pub fn indentation(
        mut self,
        left: Option<oxoffice_core::Twips>,
        hanging: Option<oxoffice_core::Twips>,
        first_line: Option<oxoffice_core::Twips>,
    ) -> Self {
        self.indent_left = left;
        self.indent_hanging = hanging;
        self.indent_first_line = first_line;
        self
    }

    /// Set properties applied only to the numbering marker.
    pub fn marker_properties(mut self, value: CT_RPr) -> Self {
        self.marker_properties = Some(value);
        self
    }

    /// Select legal-numbering placeholder behavior.
    pub fn legal_numbering(mut self, value: bool) -> Self {
        self.legal_numbering = Some(value);
        self
    }

    /// Set explicit restart behavior.
    pub fn restart(mut self, value: ListLevelRestart) -> Self {
        self.restart = Some(value);
        self
    }

    /// Set the eight-hex-digit producer template code.
    pub fn template_code(mut self, value: impl Into<String>) -> Self {
        self.template_code = Some(value.into());
        self
    }

    /// Set the producer tentative flag.
    pub fn tentative(mut self, value: bool) -> Self {
        self.tentative = Some(value);
        self
    }

    /// Return the configured level-text template, when one was supplied.
    pub fn level_text_value(&self) -> Option<&str> {
        self.level_text.as_deref()
    }

    /// Return the configured marker suffix, when one was supplied.
    pub fn suffix_value(&self) -> Option<ListLevelSuffix> {
        self.suffix
    }

    /// Return the configured marker alignment, when one was supplied.
    pub fn alignment_value(&self) -> Option<crate::paragraph::Alignment> {
        self.alignment
    }

    /// Return the configured left, hanging, and first-line indentation.
    pub fn indentation_value(
        &self,
    ) -> (
        Option<oxoffice_core::Twips>,
        Option<oxoffice_core::Twips>,
        Option<oxoffice_core::Twips>,
    ) {
        (
            self.indent_left,
            self.indent_hanging,
            self.indent_first_line,
        )
    }

    /// Return the configured marker run properties.
    pub fn marker_properties_value(&self) -> Option<&CT_RPr> {
        self.marker_properties.as_ref()
    }

    /// Return the configured legal-numbering flag.
    pub fn legal_numbering_value(&self) -> Option<bool> {
        self.legal_numbering
    }

    /// Return the configured restart behavior.
    pub fn restart_value(&self) -> Option<ListLevelRestart> {
        self.restart
    }

    /// Return the configured producer template code.
    pub fn template_code_value(&self) -> Option<&str> {
        self.template_code.as_deref()
    }

    /// Return the configured tentative flag.
    pub fn tentative_value(&self) -> Option<bool> {
        self.tentative
    }
}

/// Owned public projection of an abstract numbering definition.
#[derive(Debug, Clone, PartialEq)]
pub struct NumberingDefinition {
    /// The abstract numbering definition identifier.
    pub id: u32,
    /// The definition's ordered levels.
    pub levels: Vec<NumberingDefinitionLevel>,
    /// Imported style links, indexed in parallel with `levels`.
    pub paragraph_style_links: Vec<Option<String>>,
    /// Whether the definition contains imported properties outside this projection.
    pub has_unmodeled_properties: bool,
}

/// One explicitly identified level in an inspected numbering definition.
#[derive(Debug, Clone, PartialEq)]
pub struct NumberingDefinitionLevel {
    /// The zero-based `w:ilvl` identifier.
    pub level: u32,
    /// The modeled properties owned by this level.
    pub properties: ListLevel,
}

/// One typed override owned by a numbering instance.
#[derive(Debug, Clone, PartialEq)]
pub struct NumberingLevelOverride {
    /// The zero-based level receiving the override.
    pub level: u32,
    /// An optional starting-value override.
    pub start: Option<u32>,
    /// An optional replacement level definition.
    pub replacement: Option<ListLevel>,
    /// Imported style link for the replacement level.
    pub paragraph_style_link: Option<String>,
    /// Whether the override contains imported properties outside this projection.
    pub has_unmodeled_properties: bool,
}

impl NumberingLevelOverride {
    /// Create an empty override for a zero-based level.
    pub fn new(level: u32) -> Self {
        Self {
            level,
            start: None,
            replacement: None,
            paragraph_style_link: None,
            has_unmodeled_properties: false,
        }
    }

    /// Set the override's starting value.
    pub fn start(mut self, value: u32) -> Self {
        self.start = Some(value);
        self
    }

    /// Replace the level definition for this instance.
    pub fn replacement(mut self, value: ListLevel) -> Self {
        self.replacement = Some(value);
        self
    }
}

/// Owned public projection of one numbering instance.
#[derive(Debug, Clone, PartialEq)]
pub struct NumberingInstance {
    /// The numbering instance identifier used by document paragraphs.
    pub id: u32,
    /// The referenced abstract numbering definition identifier.
    pub definition_id: u32,
    /// Typed overrides applied by this instance.
    pub level_overrides: Vec<NumberingLevelOverride>,
    /// Whether the instance contains imported properties outside this projection.
    pub has_unmodeled_properties: bool,
}

fn list_alignment_to_st(value: crate::paragraph::Alignment) -> ST_Jc {
    match value {
        crate::paragraph::Alignment::Left => ST_Jc::Left,
        crate::paragraph::Alignment::Center => ST_Jc::Center,
        crate::paragraph::Alignment::Right => ST_Jc::Right,
        crate::paragraph::Alignment::Justify => ST_Jc::Both,
    }
}

fn list_level_restart_to_st(value: ListLevelRestart) -> Option<u32> {
    match value {
        ListLevelRestart::Never => Some(0),
        ListLevelRestart::After(level) => level.checked_add(1),
    }
}

fn list_level_from_ct(level: &CT_Lvl) -> ListLevel {
    let mut value = list_level_values_from_ct(level);
    value.source_level = Some(Box::new(level.clone()));
    value
}

fn list_level_values_from_ct(level: &CT_Lvl) -> ListLevel {
    ListLevel {
        format: level
            .num_fmt
            .clone()
            .map(list_number_format_from_st)
            .unwrap_or(ListNumberFormat::Decimal),
        start: level.start,
        level_text: level.lvl_text.clone(),
        suffix: level.suffix.map(ListLevelSuffix::from_st),
        alignment: level.lvl_jc.map(list_level_alignment),
        indent_left: level.ppr.as_ref().and_then(|value| value.ind_left),
        indent_hanging: level.ppr.as_ref().and_then(|value| value.ind_hanging),
        indent_first_line: level.ppr.as_ref().and_then(|value| value.ind_first_line),
        marker_properties: level.rpr.clone(),
        legal_numbering: level.legal,
        restart: level.restart.map(ListLevelRestart::from_st),
        template_code: level.template_code.clone(),
        tentative: level.tentative,
        source_level: None,
    }
}

pub(crate) fn list_number_format_from_st(value: ST_NumberFormat) -> ListNumberFormat {
    // Both enums intentionally have the same standard token set.
    match value.to_str() {
        "decimal" => ListNumberFormat::Decimal,
        "upperRoman" => ListNumberFormat::UpperRoman,
        "lowerRoman" => ListNumberFormat::LowerRoman,
        "upperLetter" => ListNumberFormat::UpperLetter,
        "lowerLetter" => ListNumberFormat::LowerLetter,
        "ordinal" => ListNumberFormat::Ordinal,
        "cardinalText" => ListNumberFormat::CardinalText,
        "ordinalText" => ListNumberFormat::OrdinalText,
        "hex" => ListNumberFormat::Hex,
        "chicago" => ListNumberFormat::Chicago,
        "ideographDigital" => ListNumberFormat::IdeographDigital,
        "japaneseCounting" => ListNumberFormat::JapaneseCounting,
        "Aiueo" => ListNumberFormat::Aiueo,
        "Iroha" => ListNumberFormat::Iroha,
        "decimalFullWidth" => ListNumberFormat::DecimalFullWidth,
        "decimalHalfWidth" => ListNumberFormat::DecimalHalfWidth,
        "japaneseLegal" => ListNumberFormat::JapaneseLegal,
        "japaneseDigitalTenThousand" => ListNumberFormat::JapaneseDigitalTenThousand,
        "decimalEnclosedCircle" => ListNumberFormat::DecimalEnclosedCircle,
        "decimalFullWidth2" => ListNumberFormat::DecimalFullWidth2,
        "aiueoFullWidth" => ListNumberFormat::AiueoFullWidth,
        "irohaFullWidth" => ListNumberFormat::IrohaFullWidth,
        "decimalZero" => ListNumberFormat::DecimalZero,
        "bullet" => ListNumberFormat::Bullet,
        "ganada" => ListNumberFormat::Ganada,
        "chosung" => ListNumberFormat::Chosung,
        "decimalEnclosedFullstop" => ListNumberFormat::DecimalEnclosedFullstop,
        "decimalEnclosedParen" => ListNumberFormat::DecimalEnclosedParen,
        "decimalEnclosedCircleChinese" => ListNumberFormat::DecimalEnclosedCircleChinese,
        "ideographEnclosedCircle" => ListNumberFormat::IdeographEnclosedCircle,
        "ideographTraditional" => ListNumberFormat::IdeographTraditional,
        "ideographZodiac" => ListNumberFormat::IdeographZodiac,
        "ideographZodiacTraditional" => ListNumberFormat::IdeographZodiacTraditional,
        "taiwaneseCounting" => ListNumberFormat::TaiwaneseCounting,
        "ideographLegalTraditional" => ListNumberFormat::IdeographLegalTraditional,
        "taiwaneseCountingThousand" => ListNumberFormat::TaiwaneseCountingThousand,
        "taiwaneseDigital" => ListNumberFormat::TaiwaneseDigital,
        "chineseCounting" => ListNumberFormat::ChineseCounting,
        "chineseLegalSimplified" => ListNumberFormat::ChineseLegalSimplified,
        "chineseCountingThousand" => ListNumberFormat::ChineseCountingThousand,
        "koreanDigital" => ListNumberFormat::KoreanDigital,
        "koreanCounting" => ListNumberFormat::KoreanCounting,
        "koreanLegal" => ListNumberFormat::KoreanLegal,
        "koreanDigital2" => ListNumberFormat::KoreanDigital2,
        "hebrew1" => ListNumberFormat::Hebrew1,
        "arabicAlpha" => ListNumberFormat::ArabicAlpha,
        "hebrew2" => ListNumberFormat::Hebrew2,
        "arabicAbjad" => ListNumberFormat::ArabicAbjad,
        "hindiVowels" => ListNumberFormat::HindiVowels,
        "hindiConsonants" => ListNumberFormat::HindiConsonants,
        "hindiNumbers" => ListNumberFormat::HindiNumbers,
        "hindiCounting" => ListNumberFormat::HindiCounting,
        "thaiLetters" => ListNumberFormat::ThaiLetters,
        "thaiNumbers" => ListNumberFormat::ThaiNumbers,
        "thaiCounting" => ListNumberFormat::ThaiCounting,
        "vietnameseCounting" => ListNumberFormat::VietnameseCounting,
        "numberInDash" => ListNumberFormat::NumberInDash,
        "russianLower" => ListNumberFormat::RussianLower,
        "russianUpper" => ListNumberFormat::RussianUpper,
        "none" => ListNumberFormat::None,
        other => ListNumberFormat::Other(other.to_owned()),
    }
}

fn numbering_level_has_unmodeled(level: &CT_Lvl) -> bool {
    let unprojected_paragraph_properties = level.ppr.as_ref().is_some_and(|properties| {
        let projected = CT_PPr {
            ind_left: properties.ind_left,
            ind_hanging: properties.ind_hanging,
            ind_first_line: properties.ind_first_line,
            ..CT_PPr::default()
        };
        properties != &projected
    });
    !level.extra_xml.is_empty()
        || !level.extra_attributes.is_empty()
        || level
            .start_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level
            .num_fmt_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level
            .p_style_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level
            .restart_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level
            .legal_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level
            .suffix_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level
            .lvl_text_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level
            .lvl_jc_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || level.ppr_raw.is_some()
        || level.rpr_raw.is_some()
        || unprojected_paragraph_properties
        || matches!(level.num_fmt.as_ref(), Some(ST_NumberFormat::Other(_)))
}

/// Whether a restart can copy this instance into a new one: everything it
/// holds is modelled, but namespace declarations and Word's
/// `w16cid:durableId`, which names the source instance and which the copy
/// must not take. The durable id is matched with the prefix Word writes, so
/// an attribute of that name under another prefix is refused, not dropped.
fn restart_can_copy(instance: &CT_Num) -> bool {
    instance.extra_xml.is_empty()
        && instance.extra_attributes.iter().all(|(name, _)| {
            name == "xmlns" || name.starts_with("xmlns:") || name == "w16cid:durableId"
        })
        && !instance
            .abstract_num_id_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        && !instance
            .level_overrides
            .iter()
            .any(numbering_override_has_unmodeled)
}

fn numbering_override_has_unmodeled(value: &CT_NumLvl) -> bool {
    !value.extra_xml.is_empty()
        || !value.extra_attributes.is_empty()
        || value
            .start_override_raw
            .as_ref()
            .is_some_and(|(_, raw, prefixes)| typed_numbering_leaf_has_unmodeled(raw, prefixes))
        || value
            .level
            .as_ref()
            .is_some_and(numbering_level_has_unmodeled)
}

fn validate_list_level(level: u32, value: &ListLevel) -> Result<()> {
    if level > 8 {
        return Err(Error::Other(format!(
            "numbering level {level} is outside the supported range 0 through 8"
        )));
    }
    if value.indent_hanging.is_some() && value.indent_first_line.is_some() {
        return Err(Error::Other(format!(
            "numbering level {level} cannot have both hanging and first-line indentation"
        )));
    }
    if let Some(ListLevelRestart::After(owner)) = value.restart
        && owner >= level
    {
        return Err(Error::Other(format!(
            "numbering level {level} cannot restart after level {owner}"
        )));
    }
    if let Some(template_code) = &value.template_code
        && (template_code.len() != 8 || !template_code.bytes().all(|byte| byte.is_ascii_hexdigit()))
    {
        return Err(Error::Other(format!(
            "numbering level {level} template code must contain eight hexadecimal digits"
        )));
    }
    if let Some(text) = &value.level_text {
        let bytes = text.as_bytes();
        let mut position = 0usize;
        while position < bytes.len() {
            if bytes[position] != b'%' {
                position += 1;
                continue;
            }
            let Some(next) = bytes.get(position + 1).copied() else {
                return Err(Error::Other(format!(
                    "numbering level {level} has an incomplete placeholder"
                )));
            };
            if next == b'%' {
                position += 2;
                continue;
            }
            if !(b'1'..=b'9').contains(&next) || u32::from(next - b'1') > level {
                return Err(Error::Other(format!(
                    "numbering level {level} has an invalid placeholder %{}",
                    char::from(next)
                )));
            }
            position += 2;
        }
    }
    Ok(())
}

fn default_list_level_text(level: u32, format: &ListNumberFormat) -> String {
    const BULLETS: [&str; 3] = ["\u{2022}", "\u{25E6}", "\u{25AA}"];
    match format {
        ListNumberFormat::Bullet => BULLETS[level as usize % BULLETS.len()].to_owned(),
        ListNumberFormat::None => String::new(),
        _ => format!("%{}.", level + 1),
    }
}

fn ct_level_from_list(level: u32, value: &ListLevel) -> Result<CT_Lvl> {
    validate_list_level(level, value)?;
    let mut result = CT_Lvl::new(level);
    result.template_code.clone_from(&value.template_code);
    result.tentative = value.tentative;
    result.start = Some(value.start.unwrap_or(1));
    result.num_fmt = Some(value.format.to_st());
    result.restart = value.restart.and_then(list_level_restart_to_st);
    result.legal = value.legal_numbering;
    result.suffix = value.suffix.map(|suffix| match suffix {
        ListLevelSuffix::Tab => ST_LvlSuffix::Tab,
        ListLevelSuffix::Space => ST_LvlSuffix::Space,
        ListLevelSuffix::Nothing => ST_LvlSuffix::Nothing,
    });
    result.lvl_text = Some(
        value
            .level_text
            .clone()
            .unwrap_or_else(|| default_list_level_text(level, &value.format)),
    );
    result.lvl_jc = Some(
        value
            .alignment
            .map(list_alignment_to_st)
            .unwrap_or(ST_Jc::Left),
    );
    let default_left = (level + 1)
        .checked_mul(720)
        .and_then(|value| i32::try_from(value).ok())
        .map(oxoffice_core::Twips)
        .ok_or_else(|| Error::Other(format!("numbering level {level} indentation overflow")))?;
    result.ppr = Some(CT_PPr {
        ind_left: Some(value.indent_left.unwrap_or(default_left)),
        ind_hanging: Some(value.indent_hanging.unwrap_or(oxoffice_core::Twips(360))),
        ind_first_line: value.indent_first_line,
        ..CT_PPr::default()
    });
    if value.indent_first_line.is_some() && value.indent_hanging.is_none() {
        result
            .ppr
            .as_mut()
            .expect("created paragraph properties")
            .ind_hanging = None;
    }
    result.rpr.clone_from(&value.marker_properties);
    Ok(result)
}

fn merge_list_level(existing: &CT_Lvl, value: &ListLevel) -> Result<CT_Lvl> {
    if value.source_level.as_deref() == Some(existing) {
        let source = list_level_values_from_ct(existing);
        let mut merged = existing.clone();
        if value.format != source.format {
            merged.num_fmt = Some(value.format.to_st());
        }
        if value.start != source.start {
            merged.start = value.start;
        }
        if value.level_text != source.level_text {
            merged.lvl_text.clone_from(&value.level_text);
        }
        if value.suffix != source.suffix {
            merged.suffix = value.suffix.map(|suffix| match suffix {
                ListLevelSuffix::Tab => ST_LvlSuffix::Tab,
                ListLevelSuffix::Space => ST_LvlSuffix::Space,
                ListLevelSuffix::Nothing => ST_LvlSuffix::Nothing,
            });
        }
        if value.alignment != source.alignment {
            merged.lvl_jc = value.alignment.map(list_alignment_to_st);
        }
        if value.restart != source.restart {
            merged.restart = value.restart.and_then(list_level_restart_to_st);
        }
        if value.legal_numbering != source.legal_numbering {
            merged.legal = value.legal_numbering;
        }
        if value.template_code != source.template_code {
            merged.template_code.clone_from(&value.template_code);
        }
        if value.tentative != source.tentative {
            merged.tentative = value.tentative;
        }
        if value.indentation_value() != source.indentation_value() {
            let properties = merged.ppr.get_or_insert_with(CT_PPr::default);
            properties.ind_left = value.indent_left;
            properties.ind_hanging = value.indent_hanging;
            properties.ind_first_line = value.indent_first_line;
        }
        if value.marker_properties != source.marker_properties {
            merged.rpr.clone_from(&value.marker_properties);
        }
        return Ok(merged);
    }
    let mut authored = ct_level_from_list(existing.ilvl, value)?;
    authored.start_raw.clone_from(&existing.start_raw);
    authored.num_fmt_raw.clone_from(&existing.num_fmt_raw);
    authored.p_style.clone_from(&existing.p_style);
    authored.p_style_raw.clone_from(&existing.p_style_raw);
    authored.restart_raw.clone_from(&existing.restart_raw);
    authored.legal_raw.clone_from(&existing.legal_raw);
    authored.suffix_raw.clone_from(&existing.suffix_raw);
    authored.lvl_text_raw.clone_from(&existing.lvl_text_raw);
    authored.lvl_jc_raw.clone_from(&existing.lvl_jc_raw);
    authored.extra_xml.clone_from(&existing.extra_xml);
    authored
        .extra_attributes
        .clone_from(&existing.extra_attributes);
    authored.ppr_raw.clone_from(&existing.ppr_raw);
    authored.rpr_raw.clone_from(&existing.rpr_raw);
    Ok(authored)
}

fn reject_conflicting_raw_level_attribute(level: &CT_Lvl, local_name: &[u8]) -> Result<()> {
    if level.extra_attributes.iter().any(|(name, _)| {
        name.as_bytes()
            .rsplit(|byte| *byte == b':')
            .next()
            .is_some_and(|local| local == local_name)
    }) {
        return Err(Error::Other(format!(
            "cannot replace unmodeled numbering level attribute '{}'",
            String::from_utf8_lossy(local_name)
        )));
    }
    Ok(())
}

fn validate_numbering_level_slice(levels: &[ListLevel]) -> Result<()> {
    if levels.is_empty() || levels.len() > 9 {
        return Err(Error::Other(format!(
            "numbering definitions require 1 through 9 levels, received {}",
            levels.len()
        )));
    }
    for (level, value) in levels.iter().enumerate() {
        validate_list_level(level as u32, value)?;
    }
    Ok(())
}

fn validate_numbering_definition_levels(levels: &[NumberingDefinitionLevel]) -> Result<()> {
    if levels.is_empty() || levels.len() > 9 {
        return Err(Error::Other(format!(
            "numbering definitions require 1 through 9 levels, received {}",
            levels.len()
        )));
    }
    let mut seen = HashSet::new();
    for value in levels {
        if !seen.insert(value.level) {
            return Err(Error::Other(format!(
                "numbering definition contains duplicate level {}",
                value.level
            )));
        }
        validate_list_level(value.level, &value.properties)?;
    }
    Ok(())
}

fn validate_ct_numbering_level(level: &CT_Lvl) -> Result<()> {
    if level.template_code.is_some() {
        reject_conflicting_raw_level_attribute(level, b"tplc")?;
    }
    if level.tentative.is_some() {
        reject_conflicting_raw_level_attribute(level, b"tentative")?;
    }
    validate_list_level(level.ilvl, &list_level_from_ct(level))
}

fn numbering_override_from_public(value: &NumberingLevelOverride) -> Result<CT_NumLvl> {
    if value.level > 8 {
        return Err(Error::Other(format!(
            "numbering override level {} is outside the supported range 0 through 8",
            value.level
        )));
    }
    if value.paragraph_style_link.is_some() {
        return Err(Error::Other(
            "standalone numbering style-link mutation is not supported yet".to_owned(),
        ));
    }
    if value.has_unmodeled_properties {
        return Err(Error::Other(
            "a new numbering override cannot claim imported unmodeled properties".to_owned(),
        ));
    }
    let mut result = CT_NumLvl::new(value.level);
    result.start_override = value.start;
    result.level = value
        .replacement
        .as_ref()
        .map(|level| ct_level_from_list(value.level, level))
        .transpose()?;
    Ok(result)
}

fn numbering_override_for_update(
    existing: Option<&CT_NumLvl>,
    value: &NumberingLevelOverride,
) -> Result<CT_NumLvl> {
    let Some(existing) = existing else {
        return numbering_override_from_public(value);
    };
    let existing_style = existing
        .level
        .as_ref()
        .and_then(|level| level.p_style.as_deref());
    if value.paragraph_style_link.as_deref() != existing_style {
        return Err(Error::Other(
            "standalone numbering style-link mutation is not supported yet".to_owned(),
        ));
    }
    let mut result = existing.clone();
    result.start_override = value.start;
    result.level = match (&existing.level, &value.replacement) {
        (Some(existing), Some(replacement)) => Some(merge_list_level(existing, replacement)?),
        (None, Some(replacement)) => Some(ct_level_from_list(value.level, replacement)?),
        (_, None) => None,
    };
    Ok(result)
}

fn xml_paragraph_numbering_properties(xml: &[u8]) -> Result<Vec<CT_PPr>> {
    struct ParagraphState {
        depth: usize,
        ppr_depth: Option<usize>,
        numpr_depth: Option<usize>,
        properties: CT_PPr,
    }

    fn word_value(reader: &NsReader<&[u8]>, element: &BytesStart<'_>) -> Result<Option<String>> {
        for attribute in element.attributes() {
            let attribute = attribute.map_err(|error| Error::Other(error.to_string()))?;
            let (namespace, local) = reader.resolver().resolve_attribute(attribute.key);
            if matches!(
                namespace,
                ResolveResult::Bound(value) if value.as_ref() == WORD_NAMESPACE.as_bytes()
            ) && local.as_ref() == b"val"
            {
                return attribute
                    .decoded_and_normalized_value(XmlVersion::Implicit1_0, reader.decoder())
                    .map(|value| Some(value.into_owned()))
                    .map_err(|error| Error::Other(error.to_string()));
            }
        }
        Ok(None)
    }

    fn apply_leaf(
        reader: &NsReader<&[u8]>,
        state: &mut ParagraphState,
        depth: usize,
        local_name: &[u8],
        element: &BytesStart<'_>,
    ) -> Result<()> {
        if local_name == b"pStyle" && state.ppr_depth == depth.checked_sub(1) {
            state.properties.style_id = word_value(reader, element)?;
        } else if state.numpr_depth == depth.checked_sub(1) {
            if local_name == b"numId" {
                state.properties.num_id =
                    word_value(reader, element)?.and_then(|value| value.parse::<u32>().ok());
            } else if local_name == b"ilvl" {
                state.properties.num_ilvl =
                    word_value(reader, element)?.and_then(|value| value.parse::<u32>().ok());
            }
        }
        Ok(())
    }

    let mut reader = NsReader::from_reader(xml);
    let mut buffer = Vec::new();
    let mut depth = 0_usize;
    let mut paragraphs = Vec::new();
    let mut result = Vec::new();
    loop {
        let (namespace, event) = reader
            .read_resolved_event_into(&mut buffer)
            .map_err(|error| Error::Other(error.to_string()))?;
        match event {
            Event::Start(ref element) => {
                let is_word = matches!(
                    namespace,
                    ResolveResult::Bound(value)
                        if value.as_ref() == WORD_NAMESPACE.as_bytes()
                );
                let local_name = element.local_name();
                if is_word && local_name.as_ref() == b"p" {
                    paragraphs.push(ParagraphState {
                        depth,
                        ppr_depth: None,
                        numpr_depth: None,
                        properties: CT_PPr::default(),
                    });
                } else if is_word && let Some(state) = paragraphs.last_mut() {
                    if local_name.as_ref() == b"pPr" && depth == state.depth + 1 {
                        state.ppr_depth = Some(depth);
                    } else if local_name.as_ref() == b"numPr"
                        && state.ppr_depth == depth.checked_sub(1)
                    {
                        state.numpr_depth = Some(depth);
                    } else {
                        apply_leaf(&reader, state, depth, local_name.as_ref(), element)?;
                    }
                }
                depth += 1;
            }
            Event::Empty(ref element) => {
                let is_word = matches!(
                    namespace,
                    ResolveResult::Bound(value)
                        if value.as_ref() == WORD_NAMESPACE.as_bytes()
                );
                let local_name = element.local_name();
                if is_word && local_name.as_ref() == b"p" {
                    result.push(CT_PPr::default());
                } else if is_word && let Some(state) = paragraphs.last_mut() {
                    apply_leaf(&reader, state, depth, local_name.as_ref(), element)?;
                }
            }
            Event::End(ref element) => {
                depth = depth.saturating_sub(1);
                let is_word = matches!(
                    namespace,
                    ResolveResult::Bound(value)
                        if value.as_ref() == WORD_NAMESPACE.as_bytes()
                );
                if is_word && element.local_name().as_ref() == b"p" {
                    if let Some(paragraph) = paragraphs.pop_if(|state| state.depth == depth) {
                        result.push(paragraph.properties);
                    }
                } else if let Some(state) = paragraphs.last_mut() {
                    if state.numpr_depth == Some(depth) {
                        state.numpr_depth = None;
                    }
                    if state.ppr_depth == Some(depth) {
                        state.ppr_depth = None;
                        state.numpr_depth = None;
                    }
                }
            }
            Event::Eof => return Ok(result),
            _ => {}
        }
        buffer.clear();
    }
}

fn xml_references_numbering_instance(xml: &[u8], id: u32) -> Result<bool> {
    let mut reader = NsReader::from_reader(xml);
    let mut buffer = Vec::new();
    loop {
        let (namespace, event) = reader
            .read_resolved_event_into(&mut buffer)
            .map_err(|error| Error::Other(error.to_string()))?;
        match event {
            Event::Start(ref element) | Event::Empty(ref element)
                if matches!(
                    namespace,
                    ResolveResult::Bound(value)
                        if value.as_ref() == WORD_NAMESPACE.as_bytes()
                ) && element.local_name().as_ref() == b"numId" =>
            {
                for attribute in element.attributes() {
                    let attribute = attribute.map_err(|error| Error::Other(error.to_string()))?;
                    let (namespace, local) = reader.resolver().resolve_attribute(attribute.key);
                    if !matches!(
                        namespace,
                        ResolveResult::Bound(value)
                            if value.as_ref() == WORD_NAMESPACE.as_bytes()
                    ) || local.as_ref() != b"val"
                    {
                        continue;
                    }
                    let value = attribute
                        .decoded_and_normalized_value(XmlVersion::Implicit1_0, reader.decoder())
                        .map_err(|error| Error::Other(error.to_string()))?;
                    if value.parse::<u32>().ok() == Some(id) {
                        return Ok(true);
                    }
                }
            }
            Event::Eof => return Ok(false),
            _ => {}
        }
        buffer.clear();
    }
}

/// A node in the document outline tree.
#[derive(Debug, Clone, PartialEq)]
pub struct OutlineNode {
    /// The heading level (1-9).
    pub level: u32,
    /// The heading text.
    pub text: String,
    /// Child headings (sub-headings).
    pub children: Vec<OutlineNode>,
}

/// Information about an image in the document.
#[derive(Debug, Clone, PartialEq)]
pub struct ImageInfo {
    /// The relationship ID for the embedded image.
    pub embed_id: String,
    /// Optional name attribute.
    pub name: Option<String>,
    /// Optional description (alt text).
    pub description: Option<String>,
    /// Width in EMUs (English Metric Units, 914400 EMU = 1 inch).
    pub width_emu: i64,
    /// Height in EMUs.
    pub height_emu: i64,
    /// Whether this is an anchored (floating) image vs inline.
    pub is_anchor: bool,
}

/// Information about a hyperlink in the document.
#[derive(Debug, Clone, PartialEq)]
pub struct LinkInfo {
    /// The display text of the hyperlink.
    pub text: String,
    /// The resolved target URL (if external).
    pub url: Option<String>,
    /// Internal document anchor (if any).
    pub anchor: Option<String>,
    /// The relationship ID.
    pub rel_id: Option<String>,
}

/// Severity level for accessibility issues.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IssueSeverity {
    /// Informational suggestion.
    Info,
    /// Potential problem.
    Warning,
    /// Definite accessibility barrier.
    Error,
}

/// An accessibility issue found during audit.
#[derive(Debug, Clone, PartialEq)]
pub struct AccessibilityIssue {
    /// How severe the issue is.
    pub severity: IssueSeverity,
    /// Human-readable description of the issue.
    pub message: String,
}

/// One accepted heading with its resolved visible marker and physical source.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NumberedOutlineNode {
    pub level: u32,
    pub text: String,
    pub number: Option<String>,
    pub display_text: String,
    pub source: oxoffice_docx_layout::WordSourcePath,
    pub children: Vec<NumberedOutlineNode>,
}

/// Build a hierarchical outline tree from a flat list of (level, text) headings.
fn build_outline_tree(headings: &[(u32, String)]) -> Vec<OutlineNode> {
    let mut root: Vec<OutlineNode> = Vec::new();
    let mut stack: Vec<(u32, usize)> = Vec::new(); // (level, index in parent's children)

    for (level, text) in headings {
        let node = OutlineNode {
            level: *level,
            text: text.clone(),
            children: Vec::new(),
        };

        // Pop stack until we find a parent with a lower level
        while let Some(&(stack_level, _)) = stack.last() {
            if stack_level >= *level {
                stack.pop();
            } else {
                break;
            }
        }

        if stack.is_empty() {
            root.push(node);
            let idx = root.len() - 1;
            stack.push((*level, idx));
        } else {
            // Navigate to the correct parent in the tree
            let target = get_outline_parent_mut(&mut root, &stack);
            target.children.push(node);
            let idx = target.children.len() - 1;
            stack.push((*level, idx));
        }
    }

    root
}

/// Navigate to the parent node indicated by the stack.
fn get_outline_parent_mut<'a>(
    root: &'a mut [OutlineNode],
    stack: &[(u32, usize)],
) -> &'a mut OutlineNode {
    let mut current = &mut root[stack[0].1];
    for &(_, idx) in &stack[1..] {
        current = &mut current.children[idx];
    }
    current
}

/// Truncate a string to at most `max_len` characters, appending "..." if it
/// was cut short.
///
/// Both the comparison and the cut are in characters; mixing byte length with
/// character counts would truncate non-ASCII text earlier than asked.
fn truncate_str(s: &str, max_len: usize) -> String {
    if s.chars().count() <= max_len {
        return s.to_string();
    }
    let truncated: String = s.chars().take(max_len.saturating_sub(3)).collect();
    format!("{truncated}...")
}

fn font_key_bytes(value: &str) -> Option<[u8; 16]> {
    let value_bytes = value.as_bytes();
    if value_bytes.len() != 38
        || value_bytes.first() != Some(&b'{')
        || value_bytes.last() != Some(&b'}')
        || ![9, 14, 19, 24]
            .into_iter()
            .all(|index| value_bytes.get(index) == Some(&b'-'))
        || !value_bytes.iter().enumerate().all(|(index, byte)| {
            matches!(index, 0 | 9 | 14 | 19 | 24 | 37) || matches!(byte, b'0'..=b'9' | b'A'..=b'F')
        })
    {
        return None;
    }
    let hex: String = value[1..37]
        .chars()
        .filter(|character| *character != '-')
        .collect();
    let mut guid = [0u8; 16];
    for (index, byte) in guid.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[index * 2..index * 2 + 2], 16).ok()?;
    }
    Some(guid)
}

fn obfuscate_odttf_with_key(data: &[u8], guid: &[u8; 16]) -> Vec<u8> {
    let key = odttf_key_candidates(guid)[0];
    let mut result = data.to_vec();
    for (index, byte) in result.iter_mut().take(32).enumerate() {
        *byte ^= key[index % 16];
    }
    result
}

fn deobfuscate_odttf_with_key(data: &[u8], font_key: &str) -> Option<Vec<u8>> {
    if data.len() < 32 || data.len() > 64 * 1024 * 1024 {
        return None;
    }
    let guid = font_key_bytes(font_key)?;
    let candidates = odttf_key_candidates(&guid);
    let prefixes = candidates.map(|key| {
        let mut prefix = *data.first_chunk::<32>().unwrap();
        for (index, byte) in prefix.iter_mut().enumerate() {
            *byte ^= key[index % 16];
        }
        prefix
    });
    // Producer subset headers may omit the derived binary-search hints.
    let index = prefixes
        .iter()
        .position(|prefix| has_consistent_sfnt_header(prefix))
        .or_else(|| prefixes.iter().position(|prefix| looks_like_sfnt(prefix)))?;
    let mut result = Vec::new();
    result.try_reserve_exact(data.len()).ok()?;
    result.extend_from_slice(data);
    result[..32].copy_from_slice(&prefixes[index]);
    Some(result)
}

/// Bound and check every authored single-face sfnt table before obfuscation.
fn valid_authored_sfnt(data: &[u8]) -> bool {
    if data.len() > 64 * 1024 * 1024 || !looks_like_sfnt(data) || data.starts_with(b"ttcf") {
        return false;
    }
    let count = u16::from_be_bytes([data[4], data[5]]) as usize;
    let Some(directory) = data.get(12..12 + count * 16) else {
        return false;
    };
    let mut tags = std::collections::HashSet::new();
    for record in directory.chunks_exact(16) {
        let offset = u32::from_be_bytes(record[8..12].try_into().unwrap()) as usize;
        let length = u32::from_be_bytes(record[12..16].try_into().unwrap()) as usize;
        if !tags.insert(&record[..4])
            || offset
                .checked_add(length)
                .is_none_or(|end| end > data.len())
            || (length > 0 && offset < 12 + count * 16)
        {
            return false;
        }
    }
    tags.contains(b"name".as_slice())
}

/// The two candidate XOR keys for ODTTF deobfuscation, most likely first.
fn odttf_key_candidates(guid: &[u8; 16]) -> [[u8; 16]; 2] {
    // Read the hex string end-first, as the spec prose describes.
    let mut plain_reversed = *guid;
    plain_reversed.reverse();

    // The .NET route: `Guid.ToByteArray` byte-swaps the first three groups,
    // and the whole array is then reversed.
    let dotnet = [
        guid[3], guid[2], guid[1], guid[0], guid[5], guid[4], guid[7], guid[6], guid[8], guid[9],
        guid[10], guid[11], guid[12], guid[13], guid[14], guid[15],
    ];
    let mut dotnet_reversed = dotnet;
    dotnet_reversed.reverse();

    [plain_reversed, dotnet_reversed]
}

/// Check that `data` opens with a plausible sfnt (TrueType/OpenType) header.
///
/// This is the weak test: signature plus printable table tags. It cannot always
/// tell the two ODTTF key conventions apart, since they produce identical
/// output for the first eight bytes.
fn looks_like_sfnt(data: &[u8]) -> bool {
    let Some(signature) = data.first_chunk::<4>() else {
        return false;
    };
    match signature {
        b"\x00\x01\x00\x00" | b"OTTO" | b"true" => {}
        // A collection header has a different layout; take it on signature.
        b"ttcf" => return true,
        _ => return false,
    }

    if data.len() < 32 {
        return false;
    }

    let num_tables = u16::from_be_bytes([data[4], data[5]]);
    if num_tables == 0 || num_tables > 512 {
        return false;
    }

    // Table records begin at offset 12 and are 16 bytes each, so the first
    // record's tag is at 12..16 and the second record's tag at 28..32 — both
    // inside the 32 bytes the obfuscation touches.
    let is_tag = |tag: &[u8]| tag.iter().all(|b| (0x20..=0x7E).contains(b));
    is_tag(&data[12..16]) && (num_tables < 2 || is_tag(&data[28..32]))
}

/// The strong test: the sfnt header's binary-search hints must agree with the
/// table count.
///
/// `searchRange`, `entrySelector` and `rangeShift` are all derived from
/// `numTables`, and `entrySelector`/`rangeShift` sit in the byte range where
/// the two ODTTF key conventions differ — so this identifies the right key
/// outright whenever the font's header is spec-conformant.
fn has_consistent_sfnt_header(data: &[u8]) -> bool {
    if !looks_like_sfnt(data) || data.len() < 12 {
        return false;
    }
    if data.first_chunk::<4>() == Some(b"ttcf") {
        return false; // no table directory at this offset
    }

    let num_tables = u16::from_be_bytes([data[4], data[5]]);
    let search_range = u16::from_be_bytes([data[6], data[7]]);
    let entry_selector = u16::from_be_bytes([data[8], data[9]]);
    let range_shift = u16::from_be_bytes([data[10], data[11]]);

    let expected_selector = num_tables.ilog2() as u16;
    let expected_search_range = (1u16 << expected_selector) * 16;
    let expected_range_shift = num_tables
        .wrapping_mul(16)
        .wrapping_sub(expected_search_range);

    search_range == expected_search_range
        && entry_selector == expected_selector
        && range_shift == expected_range_shift
}

fn annotate_undrawable_images(
    layout: &mut oxoffice_docx_layout::WordLayoutResult,
    input: &oxoffice_docx_layout::LayoutInput,
) {
    let mut messages = Vec::new();
    for (id, story) in layout.picture_draw_owners() {
        let key = story
            .as_ref()
            .map_or_else(|| id.clone(), |story| format!("{story}\0{id}"));
        let Some(image) = input.images.get(&key) else {
            continue;
        };
        let detail = match oxoffice_pdf::classify_image_draw(&image.data, &image.content_type) {
            oxoffice_pdf::ImageDrawClass::UnsupportedFormat { kind } => {
                format!("uses unsupported image format {kind}")
            }
            oxoffice_pdf::ImageDrawClass::CouldNotDecode => "could not be decoded".to_owned(),
            oxoffice_pdf::ImageDrawClass::Drawn | oxoffice_pdf::ImageDrawClass::NotThisDecoder => {
                continue;
            }
        };
        let mut message = format!("picture relationship {id} {detail}");
        if let Some(story) = story {
            message.push_str(&format!(" in related story {story}"));
        }
        if !messages.contains(&message) {
            messages.push(message);
        }
    }
    for message in messages {
        if !layout
            .layout
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.message == message)
        {
            layout
                .layout
                .diagnostics
                .push(oxoffice_layout::Diagnostic { message });
        }
    }
}

/// The accepted-view text of one story that the body view leaves out.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StoryText {
    /// The story the items belong to.
    pub story: StoryId,
    /// Each direct paragraph and block content control of the story.
    pub items: Vec<StoryTextItem>,
}

/// One direct paragraph or block content control of a [`StoryText`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StoryTextItem {
    /// The index path of the item inside its story.
    pub index_path: Vec<usize>,
    /// [`StoryItemKind::Paragraph`] or [`StoryItemKind::ContentControl`].
    pub kind: StoryItemKind,
    /// The accepted-view text of the item.
    pub text: String,
}

/// A diagnostic accompanying an owned accepted text projection.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TextDiagnostic {
    pub message: String,
}

/// The CLI-compatible text presentation and its explicit source scope.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TextReport {
    pub text: String,
    pub scope: &'static str,
    pub revision_view: &'static str,
    pub diagnostics: Vec<TextDiagnostic>,
}

const STORY_TEXT_RELATIONSHIPS: [&str; 5] = [
    rel_types::HEADER,
    rel_types::FOOTER,
    rel_types::FOOTNOTES,
    rel_types::ENDNOTES,
    rel_types::COMMENTS,
];

impl Document {
    /// Read every story but the main body and its table cells, which the body
    /// view already covers, in [`Document::stories`] order.
    ///
    /// Only the direct items of a story are read, so the text of an inline
    /// control or a field is not repeated after its paragraph. A table is left
    /// out because each of its cells is a table-cell story of its own.
    ///
    /// A story part that cannot be read, such as a truncated header or a
    /// header relationship to a missing part, returns the reason, naming the
    /// first part that is not well-formed XML when there is one. `validate`
    /// reports the same part as an error.
    pub fn other_story_texts(&self) -> std::result::Result<Vec<StoryText>, String> {
        self.read_other_story_texts().map_err(|error| {
            self.malformed_story_part()
                .unwrap_or_else(|| error.to_string())
        })
    }

    fn read_other_story_texts(&self) -> Result<Vec<StoryText>> {
        let mut main_part = None;
        let mut stories: Vec<StoryText> = Vec::new();
        for item in self.story_item_snapshots()? {
            let story = item.location().story();
            if story.kind() == StoryKind::Body {
                main_part = Some(story.part_name().to_owned());
                continue;
            }
            if story.kind() == StoryKind::TableCell
                && main_part.as_deref() == Some(story.part_name())
            {
                continue;
            }
            if stories.last().is_none_or(|last| &last.story != story) {
                stories.push(StoryText {
                    story: story.clone(),
                    items: Vec::new(),
                });
            }
            let kind = item.location().item_kind();
            if !matches!(
                kind,
                StoryItemKind::Paragraph | StoryItemKind::ContentControl
            ) {
                continue;
            }
            if item.is_direct_child()
                && let Some(last) = stories.last_mut()
            {
                last.items.push(StoryTextItem {
                    index_path: item.location().index_path().to_vec(),
                    kind,
                    text: item.text().unwrap_or_default().to_owned(),
                });
            }
        }
        Ok(stories)
    }

    /// Name the first story part of the main document that is not
    /// well-formed XML, with the reason.
    fn malformed_story_part(&self) -> Option<String> {
        let package = &self.package;
        let doc_part = package.main_document_part()?;
        let rels = package.get_part_rels(&doc_part)?;
        rels.items
            .iter()
            .filter(|rel| {
                rel.target_mode.as_deref() != Some("External")
                    && STORY_TEXT_RELATIONSHIPS.contains(&rel.rel_type.as_str())
            })
            .find_map(|rel| {
                let part_name = OpcPackage::resolve_rel_target(&doc_part, &rel.target);
                let detail = document_style_references(package.get_part(&part_name)?).err()?;
                Some(format!("part {part_name} is not well-formed XML: {detail}"))
            })
    }

    /// Present accepted body text followed by readable other stories.
    /// If any other story is malformed, return main-only text and the CLI warning.
    pub fn text_report(&self) -> TextReport {
        let mut text = self.text();
        let mut diagnostics = Vec::new();
        let (stories, scope) = match self.other_story_texts() {
            Ok(stories) => (stories, "all-supported-stories"),
            Err(reason) => {
                diagnostics.push(TextDiagnostic {
                    message: format!("other stories left out: {reason}"),
                });
                (Vec::new(), "main")
            }
        };
        for (kind, part_name, texts) in document_story_parts(&stories) {
            text.push_str(&format!(
                "--- {} ({part_name}) ---\n",
                document_story_kind_name(kind)
            ));
            for line in texts {
                text.push_str(line);
                text.push('\n');
            }
        }
        TextReport {
            text,
            scope,
            revision_view: "accepted",
            diagnostics,
        }
    }

    /// Count Unicode scalars in the same accepted body paragraphs as word_count.
    /// No presentation separators or story labels contribute characters.
    pub fn character_count(&self, include_spaces: bool) -> usize {
        let mut count = 0;
        visit_body_paragraphs(&self.document.body.content, true, &mut |paragraph| {
            count += paragraph
                .text()
                .chars()
                .filter(|character| include_spaces || !character.is_whitespace())
                .count();
        });
        count
    }
}
/// Group the texts of the stories by package part, each part labelled with
/// the kind of its first story, such as a header part holding table cells.
/// A part without any text, such as an empty header variant, is left out.
fn document_story_parts(stories: &[StoryText]) -> Vec<(StoryKind, &str, Vec<&str>)> {
    let mut parts: Vec<(StoryKind, &str, Vec<&str>)> = Vec::new();
    for story in stories {
        let part_name = story.story.part_name();
        if parts.last().is_none_or(|(_, last, _)| *last != part_name) {
            parts.push((story.story.kind(), part_name, Vec::new()));
        }
        if let Some((_, _, texts)) = parts.last_mut() {
            texts.extend(story.items.iter().map(|item| item.text.as_str()));
        }
    }
    parts.retain(|(_, _, texts)| texts.iter().any(|text| !text.trim().is_empty()));
    parts
}

/// One marker per pair of a [`Document::replace_all`] batch: a character of
/// the supplementary private use area between two copies of a delimiter that
/// no placeholder or value holds, so that no marker overlaps another or text
/// the caller wrote.
fn batch_markers(pairs: &[(&str, &str)]) -> Vec<String> {
    let delimiter = (0x10_FF00..=0x10_FFFD)
        .rev()
        .filter_map(char::from_u32)
        .find(|delimiter| {
            pairs.iter().all(|(placeholder, value)| {
                !placeholder.contains(*delimiter) && !value.contains(*delimiter)
            })
        })
        .unwrap_or('\u{10FFFD}');
    // The index in base 0xFF00, one private character per digit, below the
    // delimiters, so a marker never holds its delimiter.
    (0..pairs.len())
        .map(|index| {
            let mut marker = String::from(delimiter);
            let mut rest = index;
            loop {
                marker.extend(char::from_u32(0x10_0000 + (rest % 0xFF00) as u32));
                rest /= 0xFF00;
                if rest == 0 {
                    break;
                }
            }
            marker.push(delimiter);
            marker
        })
        .collect()
}

fn document_story_kind_name(kind: StoryKind) -> &'static str {
    match kind {
        StoryKind::Body => "body",
        StoryKind::TableCell => "table_cell",
        StoryKind::Header => "header",
        StoryKind::Footer => "footer",
        StoryKind::Footnote => "footnote",
        StoryKind::Endnote => "endnote",
        StoryKind::Comment => "comment",
        StoryKind::TextBox => "text_box",
    }
}

// Selected MC branches and preserved property-change subtrees determine the
// exact style-reference stream. Capabilities share the embedded-content authority.
#[derive(Default)]
struct StyleReferenceScope {
    excluded: bool,
    alternate: Option<(bool, bool, bool)>, // saw choice, selected branch, saw fallback
}

fn document_choice_supported(
    reader: &NsReader<&[u8]>,
    element: &BytesStart<'_>,
) -> std::result::Result<bool, String> {
    let mut requires = None;
    for attribute in element.attributes() {
        let attribute = attribute.map_err(|e| e.to_string())?;
        let (namespace, local) = reader.resolver().resolve_attribute(attribute.key);
        if matches!(namespace, ResolveResult::Unbound) && local.as_ref() == b"Requires" {
            if requires.is_some() {
                return Err("MC Choice has duplicate Requires".into());
            }
            requires = Some(
                attribute
                    .decoded_and_normalized_value(XmlVersion::Implicit1_0, reader.decoder())
                    .map_err(|e| e.to_string())?
                    .into_owned(),
            );
        }
    }
    Ok(requires.is_some_and(|requires| {
        let mut prefixes = requires.split_ascii_whitespace();
        prefixes.clone().next().is_some()
            && prefixes
                .all(|prefix| crate::embedded::must_understand_prefix_is_valid(reader, prefix))
    }))
}

fn document_style_references(
    xml: &[u8],
) -> std::result::Result<Vec<(&'static str, String)>, String> {
    let mut reader = NsReader::from_reader(xml);
    let mut open: Vec<StyleReferenceScope> = Vec::new();
    let mut roots = 0usize;
    let mut references = Vec::new();
    let mut buffer = Vec::new();
    loop {
        let (namespace, event) = match reader.read_resolved_event_into(&mut buffer) {
            Ok(read) => read,
            Err(error) => return Err(format!("{error} at byte {}", reader.error_position())),
        };
        let is_word =
            matches!(namespace, ResolveResult::Bound(Namespace(uri)) if uri == W_NS.as_bytes());
        let is_compatibility =
            matches!(namespace, ResolveResult::Bound(Namespace(uri)) if uri == MC_NS.as_bytes());
        match event {
            Event::Start(ref element) | Event::Empty(ref element) => {
                if open.is_empty() {
                    roots += 1;
                    if roots > 1 {
                        return Err("the part has more than one root element".into());
                    }
                }
                let local = element.local_name();
                let mut excluded = open.last().is_some_and(|scope| scope.excluded)
                    || (is_word && local.as_ref().ends_with(b"PrChange"));
                if let Some(state) = open.last_mut().and_then(|scope| scope.alternate.as_mut()) {
                    if is_compatibility && local.as_ref() == b"Choice" {
                        if state.2 {
                            return Err("MC Choice follows Fallback".into());
                        }
                        state.0 = true;
                        let selected = !state.1 && document_choice_supported(&reader, element)?;
                        state.1 |= selected;
                        excluded |= !selected;
                    } else if is_compatibility && local.as_ref() == b"Fallback" {
                        if !state.0 || state.2 {
                            return Err(
                                "MC Fallback has no preceding Choice or is duplicated".into()
                            );
                        }
                        state.2 = true;
                        excluded |= state.1;
                        state.1 = true;
                    } else {
                        // A foreign lookalike is opaque, never an admitted branch.
                        excluded = true;
                    }
                } else if is_compatibility && matches!(local.as_ref(), b"Choice" | b"Fallback") {
                    excluded = true;
                }
                let kind = match local.as_ref() {
                    b"pStyle" => Some("paragraph"),
                    b"rStyle" => Some("character"),
                    b"tblStyle" => Some("table"),
                    _ => None,
                };
                if let Some(kind) = kind.filter(|_| is_word && !excluded)
                    && let Some(style_id) = document_word_value(&reader, element)?
                    && !style_id.is_empty()
                {
                    references.push((kind, style_id));
                }
                if matches!(event, Event::Start(_)) {
                    open.push(StyleReferenceScope {
                        excluded,
                        alternate: (is_compatibility && local.as_ref() == b"AlternateContent")
                            .then_some((false, false, false)),
                    });
                }
            }
            Event::End(_) => {
                open.pop();
            }
            Event::Text(text) if open.is_empty() && !text.iter().all(u8::is_ascii_whitespace) => {
                return Err("the part has text outside its root element".into());
            }
            Event::CData(_) if open.is_empty() => {
                return Err("the part has CDATA outside its root element".into());
            }
            Event::Eof if roots == 0 => return Err("the part has no root element".into()),
            Event::Eof if !open.is_empty() => {
                return Err(format!(
                    "the part ends inside {} unclosed element(s)",
                    open.len()
                ));
            }
            Event::Eof => return Ok(references),
            _ => {}
        }
        buffer.clear();
    }
}

/// Return the `w:val` attribute of a WordprocessingML element.
fn document_word_value(
    reader: &NsReader<&[u8]>,
    element: &BytesStart<'_>,
) -> std::result::Result<Option<String>, String> {
    for attribute in element.attributes() {
        let attribute = attribute.map_err(|error| error.to_string())?;
        let (namespace, local_name) = reader.resolver().resolve_attribute(attribute.key);
        if matches!(namespace, ResolveResult::Bound(Namespace(uri)) if uri == W_NS.as_bytes())
            && local_name.as_ref() == b"val"
        {
            let value = attribute
                .decoded_and_normalized_value(XmlVersion::Implicit1_0, reader.decoder())
                .map_err(|error| error.to_string())?;
            return Ok(Some(value.into_owned()));
        }
    }
    Ok(None)
}

// Finite validator-only tables, matching the transitional body/p/r child
// inventories. These do not become parser admission or a full schema engine.
const BODY_CHILDREN: &[&str] = &["altChunk", "customXml", "sdt", "p", "tbl", "sectPr"];
const PARAGRAPH_CHILDREN: &[&str] = &[
    "pPr",
    "r",
    "bdo",
    "dir",
    "fldSimple",
    "hyperlink",
    "smartTag",
    "customXml",
    "sdt",
    "subDoc",
    "contentPart",
];
const RANGE_CHILDREN: &[&str] = &[
    "bookmarkStart",
    "bookmarkEnd",
    "commentRangeStart",
    "commentRangeEnd",
    "customXmlDelRangeStart",
    "customXmlDelRangeEnd",
    "customXmlInsRangeStart",
    "customXmlInsRangeEnd",
    "customXmlMoveFromRangeStart",
    "customXmlMoveFromRangeEnd",
    "customXmlMoveToRangeStart",
    "customXmlMoveToRangeEnd",
    "moveFromRangeStart",
    "moveFromRangeEnd",
    "moveToRangeStart",
    "moveToRangeEnd",
    "ins",
    "del",
    "moveFrom",
    "moveTo",
    "permStart",
    "permEnd",
    "proofErr",
];
const RUN_CHILDREN: &[&str] = &[
    "rPr",
    "br",
    "t",
    "delText",
    "instrText",
    "delInstrText",
    "noBreakHyphen",
    "softHyphen",
    "dayShort",
    "monthShort",
    "yearShort",
    "dayLong",
    "monthLong",
    "yearLong",
    "annotationRef",
    "footnoteRef",
    "endnoteRef",
    "separator",
    "continuationSeparator",
    "sym",
    "pgNum",
    "cr",
    "tab",
    "object",
    "pict",
    "fldChar",
    "ruby",
    "footnoteReference",
    "endnoteReference",
    "commentReference",
    "drawing",
    "ptab",
    "lastRenderedPageBreak",
    "contentPart",
];
const PARAGRAPH_JC: &[&str] = &[
    "start",
    "center",
    "end",
    "both",
    "mediumKashida",
    "distribute",
    "numTab",
    "highKashida",
    "lowKashida",
    "thaiDistribute",
    "left",
    "right",
];
const TABLE_JC: &[&str] = &["start", "center", "end", "left", "right"];
const ELEMENT_ONLY: &[&str] = &[
    "body",
    "p",
    "r",
    "pPr",
    "rPr",
    "tbl",
    "tblPr",
    "tblGrid",
    "tr",
    "trPr",
    "tc",
    "tcPr",
    "sectPr",
    "sdt",
    "sdtPr",
    "sdtContent",
    "hyperlink",
    "fldSimple",
    "smartTag",
    "customXml",
    "ins",
    "del",
    "moveFrom",
    "moveTo",
    "dir",
    "bdo",
];
const MAX_POSITIVE_COORDINATE: i64 = 27_273_042_316_900;
const MAX_STORY_FINDINGS: usize = 10;

#[derive(Clone, Copy, PartialEq, Eq)]
enum SchemaNamespace {
    Word,
    Math,
    Drawing,
    WordDrawing,
    KnownContainer,
    Foreign,
}

impl SchemaNamespace {
    fn resolved(namespace: &ResolveResult<'_>) -> Self {
        match namespace {
            ResolveResult::Bound(Namespace(uri)) if *uri == W_NS.as_bytes() => Self::Word,
            ResolveResult::Bound(Namespace(uri)) if *uri == M_NS.as_bytes() => Self::Math,
            ResolveResult::Bound(Namespace(uri)) if *uri == drawing_ns::A.as_bytes() => {
                Self::Drawing
            }
            ResolveResult::Bound(Namespace(uri)) if *uri == drawing_ns::WP.as_bytes() => {
                Self::WordDrawing
            }
            ResolveResult::Bound(Namespace(uri))
                if [
                    MC_NS.as_bytes(),
                    drawing_ns::PIC.as_bytes(),
                    b"http://schemas.microsoft.com/office/word/2010/wordprocessingShape",
                    b"http://schemas.microsoft.com/office/word/2010/wordprocessingGroup",
                    b"urn:schemas-microsoft-com:vml",
                    b"urn:schemas-microsoft-com:office:office",
                ]
                .contains(uri) =>
            {
                Self::KnownContainer
            }
            _ => Self::Foreign,
        }
    }
}

struct StoryScanFrame {
    namespace: SchemaNamespace,
    local: String,
    opaque: bool,
    deleted: bool,
    children: usize,
    section_seen: bool,
    radical_degree: bool,
    radical_expression: bool,
}

struct StoryScanContext<'a> {
    part: &'a str,
    relationships: HashSet<&'a str>,
    notes: &'a [HashSet<i32>; 2],
    findings: Vec<ValidationFinding>,
    suppressed: usize,
    suppressed_error: bool,
    bookmarks: BTreeMap<i32, usize>,
}

impl StoryScanContext<'_> {
    fn finding(&mut self, severity: ValidationSeverity, message: String) {
        if self.findings.len() < MAX_STORY_FINDINGS {
            self.findings.push(ValidationFinding {
                severity,
                message: format!("part {}: {message}", self.part),
            });
        } else {
            self.suppressed += 1;
            self.suppressed_error |= severity == ValidationSeverity::Error;
        }
    }

    fn error(&mut self, message: String) {
        self.finding(ValidationSeverity::Error, message);
    }

    fn child(&mut self, parent: &mut StoryScanFrame, namespace: SchemaNamespace, local: &str) {
        if parent.opaque || namespace == SchemaNamespace::Foreign {
            return;
        }
        if parent.namespace == SchemaNamespace::Word && namespace == SchemaNamespace::Word {
            let allowed = match parent.local.as_str() {
                "body" => Some(BODY_CHILDREN),
                "p" => Some(PARAGRAPH_CHILDREN),
                "r" => Some(RUN_CHILDREN),
                _ => None,
            };
            let range =
                matches!(parent.local.as_str(), "body" | "p") && RANGE_CHILDREN.contains(&local);
            if allowed.is_some_and(|allowed| !allowed.contains(&local) && !range) {
                self.error(format!("w:{local} is not allowed in w:{}", parent.local));
            }
            if ((parent.local == "p" && local == "pPr") || (parent.local == "r" && local == "rPr"))
                && parent.children != 0
            {
                self.error(format!(
                    "w:{local} is not the first child of w:{}",
                    parent.local
                ));
            }
            if parent.local == "body" {
                if parent.section_seen {
                    self.error(format!(
                        "w:{local} follows w:sectPr, the last child of w:body"
                    ));
                }
                parent.section_seen |= local == "sectPr";
            }
        }
        if parent.namespace == SchemaNamespace::Math
            && parent.local == "rad"
            && namespace == SchemaNamespace::Math
        {
            parent.radical_degree |= local == "deg";
            parent.radical_expression |= local == "e";
        }
        parent.children += 1;
    }

    fn close(&mut self, frame: StoryScanFrame) {
        if !frame.opaque && frame.namespace == SchemaNamespace::Math && frame.local == "rad" {
            if !frame.radical_degree {
                self.error("m:rad is missing required child m:deg".into());
            }
            if !frame.radical_expression {
                self.error("m:rad is missing required child m:e".into());
            }
        }
    }

    fn element(
        &mut self,
        reader: &NsReader<&[u8]>,
        element: &BytesStart<'_>,
        namespace: SchemaNamespace,
        open: &mut Vec<StoryScanFrame>,
        empty: bool,
    ) -> std::result::Result<(), String> {
        let local = std::str::from_utf8(element.local_name().as_ref())
            .map_err(|error| error.to_string())?
            .to_owned();
        let opaque =
            open.last().is_some_and(|frame| frame.opaque) || namespace == SchemaNamespace::Foreign;
        let deleted = open.last().is_some_and(|frame| frame.deleted)
            || (!opaque && namespace == SchemaNamespace::Word && local == "del");
        let mut attributes = BTreeMap::new();
        for attribute in element.attributes() {
            let attribute = attribute.map_err(|error| error.to_string())?;
            let (attribute_namespace, name) = reader.resolver().resolve_attribute(attribute.key);
            let value = attribute
                .decoded_and_normalized_value(XmlVersion::Implicit1_0, reader.decoder())
                .map_err(|error| error.to_string())?;
            if matches!(&attribute_namespace, ResolveResult::Bound(Namespace(uri)) if *uri == b"http://schemas.openxmlformats.org/officeDocument/2006/relationships")
                && !self.relationships.contains(value.as_ref())
            {
                self.error(format!(
                    "{}:{} references dangling relationship id {value}",
                    local,
                    String::from_utf8_lossy(name.as_ref())
                ));
            }
            if word_element(&attribute_namespace) {
                attributes.insert(name.as_ref().to_vec(), value.into_owned());
            } else if !opaque
                && matches!(
                    namespace,
                    SchemaNamespace::Drawing | SchemaNamespace::WordDrawing
                )
                && matches!(local.as_str(), "ext" | "extent")
                && matches!(attribute_namespace, ResolveResult::Unbound)
                && matches!(name.as_ref(), b"cx" | b"cy")
                && value
                    .parse::<i64>()
                    .ok()
                    .is_none_or(|value| !(0..=MAX_POSITIVE_COORDINATE).contains(&value))
            {
                self.error(format!(
                    "{local}/@{}={value:?} is not ST_PositiveCoordinate",
                    String::from_utf8_lossy(name.as_ref())
                ));
            }
        }
        if let Some(parent) = open.last_mut() {
            self.child(parent, namespace, &local);
        }
        if !opaque && namespace == SchemaNamespace::Word {
            if matches!(local.as_str(), "ins" | "del" | "moveFrom" | "moveTo") {
                for name in [b"id".as_slice(), b"author".as_slice()] {
                    if !attributes.contains_key(name) {
                        self.error(format!(
                            "w:{local} is missing required w:{}",
                            String::from_utf8_lossy(name)
                        ));
                    }
                }
            }
            if let Some(value) = attributes.get(b"val".as_slice()) {
                if local == "jc" {
                    let table = open.last().is_some_and(|frame| {
                        frame.namespace == SchemaNamespace::Word
                            && matches!(frame.local.as_str(), "tblPr" | "tblPrEx")
                    });
                    let allowed = if table { TABLE_JC } else { PARAGRAPH_JC };
                    if !allowed.contains(&value.as_str()) {
                        self.error(format!(
                            "w:jc w:val={value:?} is not an {} value",
                            if table { "ST_JcTable" } else { "ST_Jc" }
                        ));
                    }
                } else if local == "color"
                    && value != "auto"
                    && !(value.len() == 6 && value.bytes().all(|byte| byte.is_ascii_hexdigit()))
                {
                    self.error(format!("w:color w:val={value:?} is not ST_HexColor"));
                }
            }
            if matches!(local.as_str(), "footnoteReference" | "endnoteReference") {
                let family = usize::from(local == "endnoteReference");
                let value = attributes.get(b"id".as_slice());
                if value
                    .and_then(|value| value.parse::<i32>().ok())
                    .is_none_or(|id| !self.notes[family].contains(&id))
                {
                    self.error(format!(
                        "w:{local} references missing {} id {}",
                        if family == 0 { "footnote" } else { "endnote" },
                        value.map_or("(absent)", String::as_str)
                    ));
                }
            }
            if deleted && matches!(local.as_str(), "t" | "instrText") {
                self.error(format!(
                    "w:{local} inside w:del must use w:{}",
                    if local == "t" {
                        "delText"
                    } else {
                        "delInstrText"
                    }
                ));
            }
            if local == "bookmarkStart"
                && let Some(id) = attributes
                    .get(b"id".as_slice())
                    .and_then(|value| value.parse::<i32>().ok())
            {
                *self.bookmarks.entry(id).or_default() += 1;
            }
        }
        let frame = StoryScanFrame {
            namespace,
            local,
            opaque,
            deleted,
            children: 0,
            section_seen: false,
            radical_degree: false,
            radical_expression: false,
        };
        if empty {
            self.close(frame);
        } else {
            open.push(frame);
        }
        Ok(())
    }

    fn text(&mut self, open: &[StoryScanFrame], whitespace: bool) {
        if !whitespace
            && let Some(frame) = open.last()
            && !frame.opaque
            && frame.namespace == SchemaNamespace::Word
            && ELEMENT_ONLY.contains(&frame.local.as_str())
        {
            self.error(format!(
                "text directly inside w:{} is not allowed",
                frame.local
            ));
        }
    }
}

fn document_story_findings(
    package: &OpcPackage,
    part: &str,
    xml: &[u8],
    notes: &[HashSet<i32>; 2],
) -> Vec<ValidationFinding> {
    let mut context = StoryScanContext {
        part,
        relationships: package
            .get_part_rels(part)
            .into_iter()
            .flat_map(|relationships| &relationships.items)
            .map(|relationship| relationship.id.as_str())
            .collect(),
        notes,
        findings: Vec::new(),
        suppressed: 0,
        suppressed_error: false,
        bookmarks: BTreeMap::new(),
    };
    let mut reader = NsReader::from_reader(xml);
    let mut open = Vec::new();
    let mut buffer = Vec::new();
    while let Ok((namespace, event)) = reader.read_resolved_event_into(&mut buffer) {
        let namespace = SchemaNamespace::resolved(&namespace);
        match event {
            Event::Start(ref element) | Event::Empty(ref element) => {
                if context
                    .element(
                        &reader,
                        element,
                        namespace,
                        &mut open,
                        matches!(event, Event::Empty(_)),
                    )
                    .is_err()
                {
                    break;
                }
            }
            Event::End(_) => {
                if let Some(frame) = open.pop() {
                    context.close(frame);
                }
            }
            Event::Text(text) => context.text(&open, text.iter().all(u8::is_ascii_whitespace)),
            Event::CData(text) => context.text(&open, text.iter().all(u8::is_ascii_whitespace)),
            Event::GeneralRef(reference) => context.text(
                &open,
                reference
                    .resolve_char_ref()
                    .ok()
                    .flatten()
                    .is_some_and(xml_1_0_whitespace),
            ),
            Event::Eof => break,
            _ => {}
        }
        buffer.clear();
    }
    let bookmarks = std::mem::take(&mut context.bookmarks);
    for (id, count) in bookmarks {
        if count > 1 {
            context.finding(
                ValidationSeverity::Warning,
                format!("bookmark id {id} is used by {count} bookmarks"),
            );
        }
    }
    if context.suppressed != 0 {
        context.findings.push(ValidationFinding {
            severity: if context.suppressed_error {
                ValidationSeverity::Error
            } else {
                ValidationSeverity::Warning
            },
            message: format!(
                "part {part}: {} additional subset finding(s) omitted",
                context.suppressed
            ),
        });
    }
    context.findings
}

fn document_note_ids(package: &OpcPackage, relationship_type: &str, local: &[u8]) -> HashSet<i32> {
    let mut ids = HashSet::new();
    let Some(main) = package.main_document_part() else {
        return ids;
    };
    let Some(relationship) = package.get_part_rels(&main).and_then(|relationships| {
        relationships.items.iter().find(|relationship| {
            relationship.rel_type == relationship_type && relationship_is_internal(relationship)
        })
    }) else {
        return ids;
    };
    let part = OpcPackage::resolve_rel_target(&main, &relationship.target);
    let Some(xml) = package.get_part(&part) else {
        return ids;
    };
    let mut reader = NsReader::from_reader(xml);
    let mut depth = 0usize;
    let mut qualified_root = false;
    let mut buffer = Vec::new();
    while let Ok((namespace, event)) = reader.read_resolved_event_into(&mut buffer) {
        match event {
            Event::Start(ref element) | Event::Empty(ref element) => {
                if depth == 0 {
                    qualified_root = word_element(&namespace)
                        && element.local_name().as_ref()
                            == if local == b"footnote" {
                                &b"footnotes"[..]
                            } else {
                                &b"endnotes"[..]
                            };
                }
                if qualified_root
                    && depth == 1
                    && word_element(&namespace)
                    && element.local_name().as_ref() == local
                    && editable_note_owner(&reader, element).unwrap_or(false)
                {
                    for attribute in element.attributes().flatten() {
                        let (namespace, name) = reader.resolver().resolve_attribute(attribute.key);
                        if word_element(&namespace)
                            && name.as_ref() == b"id"
                            && let Ok(value) = attribute.decoded_and_normalized_value(
                                XmlVersion::Implicit1_0,
                                reader.decoder(),
                            )
                            && let Ok(id) = value.parse::<i32>()
                        {
                            ids.insert(id);
                        }
                    }
                }
                if matches!(event, Event::Start(_)) {
                    depth += 1;
                }
            }
            Event::End(_) => depth = depth.saturating_sub(1),
            Event::Eof => break,
            _ => {}
        }
        buffer.clear();
    }
    ids
}

fn document_xml_lexical_fault(xml: &[u8]) -> Option<String> {
    // Match the existing OPC UTF-8/BOM and UTF-16 signature frontier without
    // replacing or rewriting the stored part. Other encodings stay unproved.
    let utf16 = if let Some(body) = xml.strip_prefix(&[0xff, 0xfe]) {
        Some((body, true))
    } else if let Some(body) = xml.strip_prefix(&[0xfe, 0xff]) {
        Some((body, false))
    } else if xml.len() >= 4 && xml[1] == 0 && xml[3] == 0 {
        Some((xml, true))
    } else if xml.len() >= 4 && xml[0] == 0 && xml[2] == 0 {
        Some((xml, false))
    } else {
        None
    };
    let decoded;
    let xml = if let Some((body, little_endian)) = utf16 {
        if !body.len().is_multiple_of(2) {
            return Some("odd UTF-16 byte length".into());
        }
        let units = body
            .chunks_exact(2)
            .map(|pair| {
                if little_endian {
                    u16::from_le_bytes([pair[0], pair[1]])
                } else {
                    u16::from_be_bytes([pair[0], pair[1]])
                }
            })
            .collect::<Vec<_>>();
        decoded = match String::from_utf16(&units) {
            Ok(decoded) => decoded,
            Err(error) => return Some(error.to_string()),
        };
        decoded.as_bytes()
    } else {
        xml.strip_prefix(&[0xef, 0xbb, 0xbf]).unwrap_or(xml)
    };
    if let Err(error) = oxoffice_core::xml::validate_strict_xml_1_0(xml) {
        return Some(format!("{error:?}"));
    }
    let mut reader = quick_xml::Reader::from_reader(xml);
    let mut depth = 0usize;
    let mut roots = 0usize;
    let mut doctype = false;
    loop {
        let before = reader.buffer_position();
        match reader.read_event() {
            Ok(Event::Decl(_)) if before != 0 => {
                return Some("XML declaration is not first".into());
            }
            Ok(Event::DocType(_)) => {
                if doctype || roots != 0 || depth != 0 {
                    return Some("document type is not in the prolog".into());
                }
                doctype = true;
            }
            Ok(Event::Start(_)) => {
                if depth == 0 {
                    roots += 1;
                }
                depth += 1;
            }
            Ok(Event::Empty(_)) if depth == 0 => roots += 1,
            Ok(Event::End(_)) => depth = depth.saturating_sub(1),
            Ok(Event::Text(text)) if depth == 0 && !text.iter().all(u8::is_ascii_whitespace) => {
                return Some("text outside root element".into());
            }
            Ok(Event::CData(_) | Event::GeneralRef(_)) if depth == 0 => {
                return Some("text outside root element".into());
            }
            Ok(Event::Eof) => {
                return if roots == 1 && depth == 0 {
                    None
                } else {
                    Some("expected exactly one complete root element".into())
                };
            }
            Err(error) => return Some(error.to_string()),
            _ => {}
        }
    }
}

fn validate_document_read(
    read: std::result::Result<OpcPackage, oxoffice_opc::OpcError>,
) -> Result<ValidationReport> {
    match read {
        Ok(package) => validate_document_package(package),
        Err(oxoffice_opc::OpcError::InvalidXmlCharacter {
            part,
            code_point,
            line,
            column,
        }) => Ok(document_validation_report(
            vec![format!(
                "part {part} is not well-formed XML: it holds U+{code_point:04X} at line {line}, column {column}, a character XML 1.0 forbids"
            )],
            Vec::new(),
        )),
        Err(error) => Err(error.into()),
    }
}

/// Validate serialized document bytes without changing a live document.
/// Non-package input and unexplained document-open failures remain errors.
pub fn validate_document_bytes(bytes: &[u8]) -> Result<ValidationReport> {
    validate_document_read(OpcPackage::from_reader(std::io::Cursor::new(bytes)))
}

/// Validate a document package at a path with the same findings as byte validation.
pub fn validate_document_file(path: impl AsRef<Path>) -> Result<ValidationReport> {
    validate_document_read(OpcPackage::open(path))
}

fn document_validation_report(errors: Vec<String>, warnings: Vec<String>) -> ValidationReport {
    ValidationReport {
        findings: errors
            .into_iter()
            .map(|message| ValidationFinding {
                severity: ValidationSeverity::Error,
                message,
            })
            .chain(warnings.into_iter().map(|message| ValidationFinding {
                severity: ValidationSeverity::Warning,
                message,
            }))
            .collect(),
    }
}

impl Document {
    /// Validate an owned serialized snapshot, retaining this document's source and handles.
    pub fn validate(&self) -> Result<ValidationReport> {
        let mut snapshot = self.clone_for_staging();
        validate_document_bytes(&snapshot.to_bytes()?)
    }
}
fn validate_document_package(package: OpcPackage) -> Result<ValidationReport> {
    let mut errors: Vec<String> = Vec::new();
    let mut warnings: Vec<String> = Vec::new();

    // --- Structural errors ---

    // Every relationship must point at a part that is actually in the package.
    if let Some(doc_part) = package.main_document_part() {
        if package.get_part(&doc_part).is_none() {
            errors.push(format!("main document part {doc_part} is missing"));
        }
        if let Some(rels) = package.get_part_rels(&doc_part) {
            for rel in &rels.items {
                // External targets live outside the package by definition.
                if rel.target_mode.as_deref() == Some("External") {
                    continue;
                }
                let target = oxoffice_opc::OpcPackage::resolve_rel_target(&doc_part, &rel.target);
                if package.get_part(&target).is_none() {
                    errors.push(format!(
                        "relationship {} points at missing part {target}",
                        rel.id
                    ));
                    continue;
                }
                for kind in [HeaderFooterKind::Header, HeaderFooterKind::Footer] {
                    let content_type = package.content_types.content_type_for(&target);
                    if rel.rel_type == kind.relationship_type()
                        && content_type != Some(kind.content_type())
                    {
                        errors.push(format!(
                            "{} relationship {} points at {target}, which is not a WordprocessingML {} part (content type {})",
                            kind.part_stem(),
                            rel.id,
                            kind.part_stem(),
                            content_type.unwrap_or("none"),
                        ));
                    }
                }
            }
        }
    } else {
        errors.push("package declares no main document relationship".to_string());
    }

    // Every part needs a declared content type.
    for part_name in package.parts.keys() {
        if package.content_types.content_type_for(part_name).is_none() {
            errors.push(format!("part {part_name} has no declared content type"));
        }
    }

    // Markup Compatibility requires every prefix that `mc:Ignorable` or
    // `mc:MustUnderstand` lists to be declared, and a consumer may reject a
    // part that breaks the rule. A part that does not parse as XML is
    // outside this check.
    let mut xml_parts = package
        .parts
        .iter()
        .filter(|(part_name, _)| {
            package
                .content_types
                .content_type_for(part_name)
                .is_some_and(|content_type| content_type.ends_with("xml"))
        })
        .collect::<Vec<_>>();
    xml_parts.sort();
    for (part_name, xml) in xml_parts {
        let Ok(findings) = oxoffice_docx_oxml::namespace::undeclared_compatibility_prefixes(xml)
        else {
            continue;
        };
        for (attribute, prefix) in findings {
            errors.push(format!(
                "part {part_name} lists undeclared prefix `{prefix}` in mc:{attribute}"
            ));
        }
    }

    // Every XML part the main document relates to must be well formed. The
    // style ids that its story parts name are checked once the document opens.
    let mut style_references = Vec::new();
    let mut checked_xml = HashSet::new();
    let notes = [
        document_note_ids(&package, rel_types::FOOTNOTES, b"footnote"),
        document_note_ids(&package, rel_types::ENDNOTES, b"endnote"),
    ];
    if let Some(doc_part) = package.main_document_part() {
        let mut parts = BTreeMap::from([(part_name_identity(&doc_part), (doc_part.clone(), true))]);
        for rel in package
            .get_part_rels(&doc_part)
            .iter()
            .flat_map(|rels| &rels.items)
        {
            if rel.target_mode.as_deref() == Some("External") {
                continue;
            }
            let target = oxoffice_opc::OpcPackage::resolve_rel_target(&doc_part, &rel.target);
            let story = STORY_TEXT_RELATIONSHIPS.contains(&rel.rel_type.as_str());
            parts
                .entry(part_name_identity(&target))
                .and_modify(|(_, has_story_role)| *has_story_role |= story)
                .or_insert((target, story));
        }
        for (_, (part_name, story)) in parts {
            let is_xml = package
                .content_types
                .content_type_for(&part_name)
                .is_some_and(|content_type| {
                    content_type.ends_with("+xml") || content_type.ends_with("/xml")
                });
            let Some(xml) = package.get_part(&part_name).filter(|_| is_xml) else {
                continue;
            };
            if !checked_xml.insert(part_name_identity(&part_name)) {
                continue;
            }
            if let Some(detail) = document_xml_lexical_fault(xml) {
                errors.push(format!("part {part_name} is not well-formed XML: {detail}"));
                continue;
            }
            if story {
                for finding in document_story_findings(&package, &part_name, xml, &notes) {
                    match finding.severity {
                        ValidationSeverity::Error => errors.push(finding.message),
                        ValidationSeverity::Warning => warnings.push(finding.message),
                    }
                }
                match document_style_references(xml) {
                    Err(detail) => {
                        errors.push(format!("part {part_name} is not well-formed XML: {detail}"));
                    }
                    Ok(references) => style_references.extend(
                        references
                            .into_iter()
                            .map(|(kind, style_id)| (kind, style_id, part_name.clone())),
                    ),
                }
            }
        }
    }

    let mut other_xml = package
        .parts
        .iter()
        .filter(|(part, _)| {
            !checked_xml.contains(&part_name_identity(part))
                && package
                    .content_types
                    .content_type_for(part)
                    .is_some_and(|content_type| content_type.to_ascii_lowercase().ends_with("xml"))
        })
        .collect::<Vec<_>>();
    other_xml.sort_by_key(|(part, _)| *part);
    for (part, xml) in other_xml {
        if let Some(detail) = document_xml_lexical_fault(xml) {
            errors.push(format!("part {part} is not well-formed XML: {detail}"));
        }
    }

    // A malformed part can keep the document from opening. The errors found
    // so far explain why, so they are reported together with the failure.
    let doc = match Document::from_package(package) {
        Ok(doc) => doc,
        Err(error) if !errors.is_empty() => {
            errors.push(format!("the document does not open: {error}"));
            return Ok(document_validation_report(errors, warnings));
        }
        Err(error) => return Err(error),
    };

    // Word falls back to the default style for a style id that no style
    // defines, so the style that the document names is silently lost.
    for (kind, style_id, part_name) in style_references {
        let issue = format!("{kind} style {style_id:?} used in {part_name} is not defined");
        if doc.style(&style_id).is_none() && !errors.contains(&issue) {
            errors.push(issue);
        }
    }

    if let Err(error) = doc.validate_comment_ownership() {
        errors.push(format!("invalid comment ownership: {error}"));
    }

    // --- Advisory findings ---

    if doc.content_count() == 0 {
        warnings.push("Document has no content (no paragraphs or tables)".to_string());
    }

    match doc.paragraph_visibility() {
        Ok(visibility) => {
            let empty_count = visibility.iter().filter(|visible| !**visible).count();
            if empty_count > 0 {
                warnings.push(format!("{empty_count} empty paragraph(s) found"));
            }
        }
        Err(error) if !errors.is_empty() => warnings.push(format!(
            "Paragraph visibility could not be determined: {error}"
        )),
        Err(error) => return Err(error),
    }

    let mut prev_level: Option<u32> = None;
    for (level, _) in doc.headings() {
        if let Some(prev) = prev_level
            && level > prev + 1
        {
            warnings.push(format!(
                "Heading level gap: Heading{prev} -> Heading{level} (skipped level(s))"
            ));
        }
        prev_level = Some(level);
    }

    if doc.title().is_none() {
        warnings.push("Missing document title".to_string());
    }
    if doc.author().is_none() {
        warnings.push("Missing document author".to_string());
    }

    for finding in doc.validate_sections().findings {
        match finding.severity {
            ValidationSeverity::Error => errors.push(finding.message),
            ValidationSeverity::Warning => warnings.push(finding.message),
        }
    }
    Ok(document_validation_report(errors, warnings))
}
